import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['("postmenopausal women"[Title/Abstract]) AND ("glomerular filtration rate" OR eGFR OR cystatin) AND (atherosclerosis OR "intima-media thickness" OR carotid)','(postmenopausal[Title/Abstract] AND "renal function" AND (carotid OR atherosclerosis))','("healthy postmenopausal women" AND (GFR OR "glomerular filtration"))']
for q in terms:
 r=requests.get(u,params={'db':'pubmed','term':q,'retmax':20,'retmode':'json'},timeout=20); j=r.json()['esearchresult']; ids=j['idlist']; print('\nQUERY',q,'COUNT',j['count'],'IDS',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
print('\nResearch log: direct PubMed E-utilities search complete')
